+            ", handshakeTimeoutMillis=" + handshakeTimeoutMillis +
+            ", handleCloseFrames=" + handleCloseFrames +
+            ", dropPongFrames=" + dropPongFrames +
+            ", decoderConfig=" + decoderConfig +
+            "}";
+    }
+
+    public Builder toBuilder() {
+        return new Builder(this);
+    }
+
